import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

import openapiTS, { astToString } from 'openapi-typescript';

const root = new URL('../', import.meta.url);
const contract = new URL('../../docs/openapi.json', import.meta.url);
const committedPath = new URL('../src/generated/api.d.ts', import.meta.url);

const HEADER = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;

const ast = await openapiTS(contract);
const generated = HEADER + astToString(ast);
const committed = await readFile(committedPath, 'utf8');

if (generated !== committed) {
  console.error(
    `Generated API types are out of date.\nRun "npm run api:generate" in ${fileURLToPath(root)} and commit the result.`,
  );
  process.exit(1);
}

console.log('Generated API types match the published OpenAPI contract.');
